async function POST(request) {
  const body = await request.json();
  if (!body.title) {
    return Response.json({ error: "title required" }, { status: 400 });
  }
  return Response.json({ id: 1, title: body.title }, { status: 201 });
}

const call = (body) =>
  POST(new Request("http://x.test/api/todos", { method: "POST", body: JSON.stringify(body) }))
    .then((r) => r.status);

(async () => {
  console.log(await call({ title: "Học Next" }));
  console.log(await call({}));
})();
